offbox run --bg -- 'set -eu; task_tmp=$(mktemp -d "$PWD/.mac104-tests.XXXXXX"); export TMPDIR="$task_tmp" PYTHONDONTWRITEBYTECODE=1; if ! command -v uv >/dev/null; then curl -LsSf https://astral.sh/uv/install.sh -o "$task_tmp/uv-install.sh"; sh "$task_tmp/uv-install.sh"; export PATH="$HOME/.local/bin:$PATH"; fi; uv python install 3.9 3.12; uv run --no-project --python 3.9 python --version; uv run --no-project --python 3.9 python -m unittest discover -s integrations/mac-logging/tests -p "test_deep*.py" -v; uv run --no-project --python 3.12 python --version; uv run --no-project --python 3.12 python -m unittest discover -s integrations/mac-logging/tests -p "test_deep*.py" -v'
